198	func newGPUBlocks(dev *vk.Device, blocks []*SnakeResBlock, frames int, kernel ConvKernel,
199		up *upWeights, _ bool) (*GPUBlocks, error) {
200		if len(blocks) == 0 {
201			return nil, fmt.Errorf("kokoro: no blocks")
202		}
203		c := blocks[0].Channels
204		if c&(c-1) != 0 {
205			return nil, fmt.Errorf("kokoro: %d channels is not a power of two", c)
