198	func newGPUBlocks(dev *vk.Device, blocks []*SnakeResBlock, frames int, kernel ConvKernel,
199		up *upWeights, _ bool) (*GPUBlocks, error) {
200		if len(blocks) == 0 {
201			return nil, fmt.Errorf("kokoro: no blocks")
202		}
203		c := blocks[0].Channels
204		if c&(c-1) != 0 {
205			return nil, fmt.Errorf("kokoro: %d channels is not a power of two", c)
206		}
207		g := &GPUBlocks{
208			dev: dev, frames: frames, framesPad: roundUp(frames, framePad),
209			channels: c, lda: c, kernel: kernel, up: up,
210			pipes: map[string]*vk.ComputePipeline{},
211			convs: map[ConvKernel]*vk.ComputePipeline{},
212		}
213		for _, b := range blocks {
214			if b.Channels != c {
215				return nil, fmt.Errorf("kokoro: blocks of %d and %d channels in one set", c, b.Channels)
216			}
217		}
218		if err := g.alloc(blocks); err != nil {
219			g.Destroy()
220			return nil, err
221		}
222		if err := g.build(); err != nil {
223			g.Destroy()
224			return nil, err
225		}
226		if err := g.stage(blocks); err != nil {
227			g.Destroy()
228			return nil, err
229		}
230		return g, nil
231	}
