242	// SetKernel switches rungs. The weights are staged as fragment tiles, which
243	// every rung reads, so this needs no restaging — the same property that makes
244	// parakeet's GEMM ladder one load instead of eight.
245	func (g *GPUBlocks) SetKernel(k ConvKernel) error {
246		if _, ok := g.convs[k]; !ok {
247			return fmt.Errorf("kokoro: no pipeline for %q", k)
248		}
249		g.kernel = k
250		return nil
251	}
