253	func (g *GPUBlocks) alloc(blocks []*SnakeResBlock) error {
254		c := g.channels
255		var off32 uint32
256		take32 := func(n int) uint32 { o := off32; off32 += uint32(n); return o }
257		// The stage's input is held once and copied into the running value before
258		// each block, because the generator runs three blocks over the *same*
259		// input and averages them. Uploading it three times would cost more than
260		// the blocks do.
261		g.aIn = take32(g.framesPad * c)
262		g.aX = take32(g.framesPad * c)
263		g.aSum = take32(g.framesPad * c)
264		g.aC = take32(g.framesPad * c)
265		g.aStat = take32(statChunks * 2 * c)
266		g.aAff = take32(2 * c)
267		if g.up != nil {
268			// The excitation's own residual block runs in place in this arena,
269			// so the noise path never touches the running value.
270			g.aNoise = take32(g.framesPad * c)
271			g.aXin = take32(roundUp(g.up.inFrames, framePad) * g.up.inCh)
272			// The upsampler writes (T_in+1) rows of stride*C, which read as
273			// [(T_in+1)*stride, C] is the signal offset by stride/2.
274			g.aUp = take32(roundUp(g.up.inFrames+1, framePad) * g.up.stride * c)
275		}
276		g.actElems = int(off32)
277	
278		// One fp16 A operand, bordered at both ends. Only one is live at a time:
279		// the fused activation pass writes it and the convolution reads it.
280		g.hElems = (2*convBorder + g.framesPad) * g.lda
281		g.hA = uint32(convBorder * g.lda)
282		if g.up != nil {
283			// A second bordered arena, at the *input* width: the upsampler's two
284			// taps read frames q-1 and q, so both ends need a zero row.
285			g.hUp = uint32(g.hElems + convBorder*g.up.ldaIn)
286			g.hElems += (2*convBorder + roundUp(g.up.inFrames+1, framePad)) * g.up.ldaIn
287		}
288	
289		// fp32 weights: per block per iteration, two alphas, one bias and two
290		// pairs of style coefficients.
291		var offW uint32
292		for range blocks {
293			offW += 3 * uint32(5*c+2*c) // alpha1, alpha2, bias2, gb1, gb2
294		}
295		if g.up != nil {
296			offW += uint32(g.up.outCh)
297		}
298		g.wNext = 0
299	
300		var err error
301		if g.abuf, err = g.dev.NewBuffer(g.actElems * 4); err != nil {
302			return fmt.Errorf("kokoro: fp32 arena: %w", err)
303		}
304		if g.hbuf, err = g.dev.NewBuffer(g.hElems * 2); err != nil {
305			return fmt.Errorf("kokoro: fp16 arena: %w", err)
306		}
307		if g.wbuf, err = g.dev.NewBuffer(int(offW) * 4); err != nil {
308			return fmt.Errorf("kokoro: fp32 weights: %w", err)
309		}
310		// Fragment tiles for every convolution: N = C rows of K = taps*C.
311		var halves int
312		for _, b := range blocks {
313			for i := range b.Convs1 {
314				halves += c * b.Convs1[i].Kernel * c
315				halves += c * b.Convs2[i].Kernel * c
316			}
317		}
318		if g.up != nil {
319			halves += g.up.stride * g.up.outCh * 2 * g.up.inCh
320		}
321		g.bank, err = g.dev.NewBuffer(halves * 2)
322		if err != nil {
323			return fmt.Errorf("kokoro: weight bank: %w", err)
324		}
325		return nil
326	}
