328	func (g *GPUBlocks) build() error {
329		arenas := []*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.bank}
330		spec := vk.PipelineSpec{Buffers: arenas, PushConstantSize: uint32(unsafe.Sizeof(pushConstants{}))}
331		for _, s := range []struct {
332			name  string
333			spirv []byte
334		}{
335			{"stats", shaders.KokoroStats},
336			{"affine", shaders.KokoroAffine},
337			{"act", shaders.KokoroAct},
338			{"snake", shaders.KokoroActSnake},
339			{"residual", shaders.KokoroResidual},
340			{"copy", shaders.KokoroCopy},
341			{"leaky", shaders.KokoroActLeaky},
342			{"upadd", shaders.KokoroUpAdd},
343			{"upaddpad", shaders.KokoroUpAddPad},
344		} {
345			if err := g.pipeline(s.name, s.spirv, spec); err != nil {
346				return err
347			}
348		}
349		for _, v := range convVariants {
350			s := spec
351			s.RequiredSubgroupSize = v.wave
352			if v.wave != 0 {
353				ok, err := canPinWave(g.dev, v.wave)
354				if err != nil {
355					return err
356				}
357				if !ok {
358					continue
359				}
360			}
361			mod, err := g.dev.NewShaderModule(v.spirv)
362			if err != nil {
363				return fmt.Errorf("kokoro: shader %s: %w", v.name, err)
364			}
365			g.mods = append(g.mods, mod)
366			pipe, err := g.dev.NewPipeline(mod, s)
367			if err != nil {
368				return fmt.Errorf("kokoro: pipeline %s: %w", v.name, err)
369			}
370			g.convs[v.name] = pipe
371		}
372		if _, ok := g.convs[g.kernel]; !ok {
373			return fmt.Errorf("kokoro: convolution kernel %q is not available on this device", g.kernel)
374		}
375		return nil
376	}
