378	// canPinWave reports whether the device lets a compute pipeline demand the
379	// given subgroup size. The wave32 rungs are useless without it, and §6.2
380	// measured wave32 beating wave64 on every shape either vertical has run.
381	func canPinWave(dev *vk.Device, wave uint32) (bool, error) {
382		if wave == 0 {
383			return true, nil
384		}
385		if !dev.Features().SubgroupSizeControl {
386			return false, nil
387		}
388		sgs, err := dev.Physical().SubgroupSizeControl()
389		if err != nil {
390			return false, fmt.Errorf("kokoro: subgroup size control: %w", err)
391		}
392		return sgs.Supported && wave >= sgs.MinSubgroupSize && wave <= sgs.MaxSubgroupSize, nil
393	}
