409	// stage writes the weights: fp16 fragment tiles for the convolutions, fp32
410	// for everything read elementwise.
411	//
412	// convs1's bias is not staged at all. Its output goes straight into an AdaIN,
413	// which subtracts the per-channel mean over time — a per-channel constant
414	// moves that mean by exactly itself and leaves the variance alone, so the
415	// bias cancels identically. TestGPUBiasCancels holds that to the CPU.
416	func (g *GPUBlocks) stage(blocks []*SnakeResBlock) error {
417		c := g.channels
418		bank := make([]uint16, g.bank.Size()/2)
419		w32 := make([]float32, g.wbuf.Size()/4)
420		var bankOff, wOff uint32
421		takeW := func(v []float32) uint32 {
422			o := wOff
423			copy(w32[o:], v)
424			wOff += uint32(len(v))
425			return o
426		}
427		for _, b := range blocks {
428			bw := blockWeights{}
429			for i := range b.Convs1 {
430				c1, c2 := b.Convs1[i], b.Convs2[i]
431				if c1.In != c || c1.Out != c || c2.In != c || c2.Out != c {
432					return fmt.Errorf("kokoro: resblock convolution %d->%d, want %d->%d", c1.In, c1.Out, c, c)
433				}
434				bw.k1[i], bw.k2[i], bw.d1[i] = c1.Kernel, c2.Kernel, c1.Dilation
435				bw.b1Off[i] = bankOff
436				packConvB(bank[bankOff:], c1.Weight, c, c, c1.Kernel)
437				bankOff += uint32(c * c * c1.Kernel)
438				bw.b2Off[i] = bankOff
439				packConvB(bank[bankOff:], c2.Weight, c, c, c2.Kernel)
440				bankOff += uint32(c * c * c2.Kernel)
441	
442				bw.alpha1[i] = takeW(b.Alpha1[i])
443				bw.alpha2[i] = takeW(b.Alpha2[i])
444				bw.bias2[i] = takeW(c2.Bias)
445				// The style coefficients are written by SetStyle; reserve them.
446				bw.gb1[i] = takeW(make([]float32, 2*c))
447				bw.gb2[i] = takeW(make([]float32, 2*c))
448				bw.fc1[i], bw.fc2[i] = b.Norm1[i].FC, b.Norm2[i].FC
449			}
450			g.blocks = append(g.blocks, bw)
451		}
452		if g.up != nil {
453			u := g.up
454			u.bias = takeW(u.conv.Bias)
455			u.bOff = bankOff
456			packUpB(bank[bankOff:], u.conv.Weight, u.inCh, u.outCh, u.stride)
457			bankOff += uint32(u.stride * u.outCh * 2 * u.inCh)
458			u.conv = nil
459		}
460		g.bank.WriteUint16At(0, bank)
461		g.wbuf.WriteFloat32At(0, w32)
462		// The fp16 arena's border has to be zero before the first convolution
463		// reads it, and nothing writes it afterwards.
464		g.hbuf.WriteUint16At(0, make([]uint16, g.hElems))
465		return nil
466	}
467	
468	// packConvB lays a [Out, In, taps] convolution weight out as the 16x16
469	// fragment tiles B_LAYOUT=2 reads, with the K index being tap*In + in — which
470	// is the order dit_gemm.comp's A_CONV walks the activation in.
471	func packConvB(dst []uint16, w []float32, out, in, taps int) {
472		k := taps * in
473		kt := k / coopMatTile
474		parallelFor(out, func(o int) {
475			base := (o / coopMatTile) * kt * coopMatTile * coopMatTile
476			lane := (o % coopMatTile) * coopMatTile
477			for i := 0; i < in; i++ {
478				for j := 0; j < taps; j++ {
479					kk := j*in + i
480					dst[base+(kk/coopMatTile)*coopMatTile*coopMatTile+lane+kk%coopMatTile] =
481						safetensors.F32ToF16(w[(o*in+i)*taps+j])
482				}
483			}
484		})
485	}
486	
487	// SetStyle computes every AdaIN's gamma and beta for one utterance.
488	//
489	// This is the whole cost of the style conditioning on the device: nothing. The
490	// `fc` layers are [2C, 128] projections of a single vector, so they run once
491	// on the host and what reaches the graph is two numbers per channel — which is
492	// also why kokoro_affine.comp never sees the style at all.
493	func (g *GPUBlocks) SetStyle(style []float32) error {
494		c := g.channels
495		buf := make([]float32, 2*c)
496		for _, bw := range g.blocks {
497			for i := 0; i < 3; i++ {
498				for _, s := range []struct {
499					fc  *Linear
500					off uint32
501				}{{bw.fc1[i], bw.gb1[i]}, {bw.fc2[i], bw.gb2[i]}} {
502					if s.fc.Out != 2*c {
503						return fmt.Errorf("kokoro: style projection is %d wide, want %d", s.fc.Out, 2*c)
504					}
505					s.fc.ApplyRow(buf, style)
506					g.wbuf.WriteFloat32At(int(s.off), buf)
507				}
508			}
509		}
510		return nil
511	}
