513	// graph builds one block's dispatch sequence, with a label per dispatch.
514	func (g *GPUBlocks) graph(block int) ([]vk.MultiDispatch, []string, error) {
515		return g.graphAt(block, g.aX)
516	}
517	
518	// graphAt builds a block's sequence over a caller-chosen running value, so
519	// the excitation's block can run in its own arena rather than through the one
520	// the generator's three share.
521	func (g *GPUBlocks) graphAt(block int, aX uint32) ([]vk.MultiDispatch, []string, error) {
522		bw := &g.blocks[block]
523		c := uint32(g.channels)
524		logC := uint32(math.Log2(float64(g.channels)))
525		rows := uint32(g.frames)
526		perChunk := uint32(roundUp(g.frames, statChunks) / statChunks)
527	
528		var d []vk.MultiDispatch
529		var kinds []string
530		add := func(pipe *vk.ComputePipeline, kind string, gx uint32, pc pushConstants) {
531			d = append(d, vk.MultiDispatch{Pipeline: pipe, GroupsX: gx, GroupsY: 1, PushConstants: pc.bytes()})
532			kinds = append(kinds, kind)
533		}
534		base := pushConstants{Tokens: rows, Dim: c, Aux2: logC, Eps: math.Float32bits(float32(instanceNormEps))}
535	
536		// AdaIN over time, then Snake, then the narrow into the bordered arena.
537		adain := func(kind string, src, gb, alpha uint32) {
538			pc := base
539			pc.InOff, pc.OutOff, pc.Aux0 = src, g.aStat, perChunk
540			add(g.pipes["stats"], kind+" stats", statChunks, pc)
541	
542			pc = base
543			pc.InOff, pc.OutOff, pc.WOff, pc.Aux0 = g.aStat, g.aAff, gb, statChunks
544			add(g.pipes["affine"], kind+" affine", 1, pc)
545	
546			pc = base
547			pc.InOff, pc.OutOff, pc.WOff, pc.Aux0 = src, g.hA, alpha, g.aAff
548			pc.LDA = uint32(g.lda)
549			add(g.pipes["snake"], kind+" snake", groups(g.frames*g.channels, 256), pc)
550		}
551		// One convolution: C[t, o] = sum over taps and input channels, with the
552		// im2col implicit in the A operand's addressing.
553		conv := func(kind string, bOff uint32, taps, dilation int, out uint32) error {
554			v, ok := convVariantFor(g.kernel)
555			if !ok {
556				return fmt.Errorf("kokoro: no variant %q", g.kernel)
557			}
558			if g.channels%v.bn != 0 {
559				return fmt.Errorf("kokoro: tile width %d does not divide %d channels", v.bn, g.channels)
560			}
561			m := roundUp(g.frames, v.bm)
562			pad := (taps - 1) * dilation / 2
563			pc := base
564			// inOff points at the row the first tap reads, which is `pad` frames
565			// before the output frame — the border makes that address legal.
566			pc.InOff = g.hA - uint32(pad*g.lda)
567			pc.OutOff, pc.BOff = out, bOff
568			pc.GemmM, pc.GemmN, pc.GemmK = uint32(m), c, uint32(taps*g.channels)
569			pc.LDA = uint32(g.lda)
570			pc.Aux0, pc.Aux1, pc.Aux2 = c, uint32(dilation*g.lda), logC
571			d = append(d, vk.MultiDispatch{
572				Pipeline: g.convs[g.kernel], GroupsX: uint32(g.channels / v.bn), GroupsY: uint32(m / v.bm),
573				PushConstants: pc.bytes(),
574			})
575			kinds = append(kinds, kind)
576			return nil
577		}
578	
579		for i := 0; i < 3; i++ {
580			adain(fmt.Sprintf("norm1.%d", i), aX, bw.gb1[i], bw.alpha1[i])
581			if err := conv(fmt.Sprintf("conv1.%d k=%d d=%d", i, bw.k1[i], bw.d1[i]),
582				bw.b1Off[i], bw.k1[i], bw.d1[i], g.aC); err != nil {
583				return nil, nil, err
584			}
585			adain(fmt.Sprintf("norm2.%d", i), g.aC, bw.gb2[i], bw.alpha2[i])
586			if err := conv(fmt.Sprintf("conv2.%d k=%d", i, bw.k2[i]),
587				bw.b2Off[i], bw.k2[i], 1, g.aC); err != nil {
588				return nil, nil, err
589			}
590			pc := base
591			pc.InOff, pc.OutOff, pc.WOff = g.aC, aX, bw.bias2[i]
592			add(g.pipes["residual"], fmt.Sprintf("residual.%d", i), groups(g.frames*g.channels, 256), pc)
593		}
594		return d, kinds, nil
595	}
