621	// elementwise is one dispatch of a pass that walks [T, C] linearly.
622	func (g *GPUBlocks) elementwise(pipe string, in, out, w uint32) vk.MultiDispatch {
623		pc := pushConstants{Tokens: uint32(g.frames), Dim: uint32(g.channels), InOff: in, OutOff: out, WOff: w}
624		return vk.MultiDispatch{
625			Pipeline: g.pipes[pipe], GroupsX: groups(g.frames*g.channels, 256), GroupsY: 1,
626			PushConstants: pc.bytes(),
627		}
