630	// Run executes one block over the uploaded input, leaving the result in the
631	// running value.
632	func (g *GPUBlocks) Run(block int) error {
633		d, _, err := g.graph(block)
634		if err != nil {
635			return err
636		}
637		d = append([]vk.MultiDispatch{g.elementwise("copy", g.aIn, g.aX, noW)}, d...)
638		return submit(d)
639	}
640	
641	// Average runs several blocks over the same input and averages them, which is
642	// the generator's multi-receptive-field fusion: three filters of 3, 7 and 11
643	// taps over one activation, summed and divided by three.
644	//
645	// Nothing crosses the bus between them. The input is copied into the running
646	// value on the device before each block and the sum accumulates in a third
647	// arena, so a stage is one upload and one download however many blocks it has.
648	func (g *GPUBlocks) Average(blocks []int) (*Mat, error) {
649		if len(blocks) == 0 {
650			return nil, fmt.Errorf("kokoro: no blocks to average")
651		}
652		var d []vk.MultiDispatch
653		for j, b := range blocks {
654			g0, _, err := g.graph(b)
655			if err != nil {
656				return nil, err
657			}
658			d = append(d, g.elementwise("copy", g.aIn, g.aX, noW))
659			d = append(d, g0...)
660			if j == 0 {
661				d = append(d, g.elementwise("copy", g.aX, g.aSum, noW))
662			} else {
663				d = append(d, g.elementwise("residual", g.aX, g.aSum, noW))
664			}
665		}
666		if err := submit(d); err != nil {
667			return nil, err
668		}
669		out := &Mat{Rows: g.frames, Cols: g.channels,
670			Data: g.abuf.ReadFloat32At(int(g.aSum), g.frames*g.channels)}
671		inv := 1 / float32(len(blocks))
672		for i := range out.Data {
673			out.Data[i] *= inv
674		}
675		return out, nil
676	}
677	
678	// ApplyOne runs a single block, which is what a correctness check wants and
679	// not what the pipeline does.
680	func (g *GPUBlocks) ApplyOne(block int, x *Mat) (*Mat, error) {
681		if err := g.Upload(x); err != nil {
682			return nil, err
683		}
684		if err := g.Run(block); err != nil {
685			return nil, err
686		}
687		return g.Download(), nil
688	}
689	
690	// perSubmit caps how many dispatches go into one command buffer, the same
691	// bound parakeet's graph uses.
692	const perSubmit = 240
693	
694	func submit(d []vk.MultiDispatch) error {
695		for len(d) > 0 {
696			n := min(len(d), perSubmit)
697			if _, err := vk.DispatchMultiTimed(d[:n], 1, 1, true); err != nil {
698				return err
699			}
700			d = d[n:]
701		}
702		return nil
