468	// packConvB lays a [Out, In, taps] convolution weight out as the 16x16
469	// fragment tiles B_LAYOUT=2 reads, with the K index being tap*In + in — which
470	// is the order dit_gemm.comp's A_CONV walks the activation in.
471	func packConvB(dst []uint16, w []float32, out, in, taps int) {
472		k := taps * in
473		kt := k / coopMatTile
474		parallelFor(out, func(o int) {
475			base := (o / coopMatTile) * kt * coopMatTile * coopMatTile
476			lane := (o % coopMatTile) * coopMatTile
477			for i := 0; i < in; i++ {
478				for j := 0; j < taps; j++ {
479					kk := j*in + i
480					dst[base+(kk/coopMatTile)*coopMatTile*coopMatTile+lane+kk%coopMatTile] =
481						safetensors.F32ToF16(w[(o*in+i)*taps+j])
482				}
483			}
484		})
485	}
