641	// Average runs several blocks over the same input and averages them, which is
642	// the generator's multi-receptive-field fusion: three filters of 3, 7 and 11
643	// taps over one activation, summed and divided by three.
644	//
645	// Nothing crosses the bus between them. The input is copied into the running
646	// value on the device before each block and the sum accumulates in a third
647	// arena, so a stage is one upload and one download however many blocks it has.
648	func (g *GPUBlocks) Average(blocks []int) (*Mat, error) {
649		if len(blocks) == 0 {
650			return nil, fmt.Errorf("kokoro: no blocks to average")
651		}
652		var d []vk.MultiDispatch
653		for j, b := range blocks {
654			g0, _, err := g.graph(b)
655			if err != nil {
656				return nil, err
657			}
658			d = append(d, g.elementwise("copy", g.aIn, g.aX, noW))
659			d = append(d, g0...)
660			if j == 0 {
661				d = append(d, g.elementwise("copy", g.aX, g.aSum, noW))
662			} else {
663				d = append(d, g.elementwise("residual", g.aX, g.aSum, noW))
664			}
665		}
666		if err := submit(d); err != nil {
667			return nil, err
668		}
669		out := &Mat{Rows: g.frames, Cols: g.channels,
670			Data: g.abuf.ReadFloat32At(int(g.aSum), g.frames*g.channels)}
671		inv := 1 / float32(len(blocks))
672		for i := range out.Data {
673			out.Data[i] *= inv
674		}
675		return out, nil
676	}
