794	// packUpB lays a ConvTranspose1d weight out as the one GEMM described on
795	// upWeights: N = stride*outCh, K = 2*inCh.
796	//
797	// Output frame q*s + r reads input frames q-1 and q, with taps r+s and r. The
798	// A operand walks the two input rows in that order (the earlier one first,
799	// which is what makes the tap stride a positive lda), so tap 0 of the B
800	// operand is the *later* weight index.
801	func packUpB(dst []uint16, w []float32, in, out, stride int) {
802		n, k := stride*out, 2*in
803		kt := k / coopMatTile
804		taps := 2 * stride
805		parallelFor(n, func(row int) {
806			r, o := row/out, row%out
807			base := (row / coopMatTile) * kt * coopMatTile * coopMatTile
808			lane := (row % coopMatTile) * coopMatTile
809			for i := 0; i < in; i++ {
810				for jj := 0; jj < 2; jj++ {
811					m := r + stride
812					if jj == 1 {
813						m = r
814					}
815					kk := jj*in + i
816					dst[base+(kk/coopMatTile)*coopMatTile*coopMatTile+lane+kk%coopMatTile] =
817						safetensors.F32ToF16(w[(i*out+o)*taps+m])
818				}
819			}
820		})
821	}
