			har.Data[tt*2*bins+bins+b] = refPlane(t, m, "har_phase", b, tt)
		}
	}
	exact, gtr, err := v.Generator.ApplyWithHarmonic(x, decStyle, har)
	if err != nil {
		t.Fatal(err)
	}

