func (g *GPUBlocks) stageDispatches() ([]vk.MultiDispatch, error) {
	if g.up == nil {
		return nil, fmt.Errorf("kokoro: this block set has no upsampler")
	}
	// The excitation's residual block runs in its own arena, in place, so it
