	}
	a.buf = buf
	return nil
}

func (a *sharedArena) destroy() {
	if a.buf != nil {
		a.buf.Destroy()
		a.buf = nil
	}
}

func roundUp(n, m int) int { return (n + m - 1) / m * m }"""
