	out := Context{FutureVowel: c.FutureVowel}
	for _, r := range phonemes {
		if !vowels[r] && !consonants[r] && !nonQuotePuncts[r] {
			continue
		}
		if nonQuotePuncts[r] {
			out.FutureVowel = nil
		} else {
