1	package g2p
2	
3	import (
4		"bufio"
5		"fmt"
6		"os"
7		"path/filepath"
8		"regexp"
9		"strings"
10		"unicode"
11	)
12	
13	// Ratings are misaki's confidence in a pronunciation, and they are worth
14	// keeping because they say which mechanism produced it: 4 is the hand-checked
15	// gold dictionary, 3 the generated silver one or a proper noun spelled out
16	// letter by letter, and 2 the espeak fallback (which this package does not
17	// have yet).
18	const (
19		RatingGold   = 4
20		RatingSilver = 3
21		RatingEspeak = 2
22	)
23	
24	// entry is one dictionary line: either a single pronunciation or one per
25	// part-of-speech tag.
26	//
27	// A tag mapping to the empty string is misaki's JSON `null`, and it does not
28	// mean "no pronunciation" — it means *this* tag has none, so the lookup falls
29	// through to the proper-noun path rather than to DEFAULT. 67 gold entries are
30	// like that, and collapsing them onto DEFAULT would mispronounce every one.
31	type entry struct {
32		plain string
33		byTag map[string]string
34	}
35	
36	func (e entry) conditioned() bool { return e.byTag != nil }
37	
38	// Lexicon is misaki's English dictionary and the rules that reach past it.
39	//
40	// Two dictionaries, not one, and the order matters: `gold` is hand-checked and
41	// `silver` generated, so a word in both takes gold's pronunciation and gold's
42	// rating. Together they resolve 91% of the tokens in real running text.
43	type Lexicon struct {
44		British bool
45	
46		gold   map[string]entry
47		silver map[string]entry
48	
49		// capStresses is misaki's (0.5, 2): the stress level a capitalised word
50		// gets and the one an all-caps word gets. Nothing else raises it.
51		capStresses [2]float64
