55	// passes through. `.` and `/` are only spoken when spacy tags them ADD, which
56	// is what it does inside a URL or an email address.
57	var (
58		symbols    = map[string]string{"%": "percent", "&": "and", "+": "plus", "@": "at"}
59		addSymbols = map[string]string{".": "dot", "/": "slash"}
60		usTaus     = runeSet("AIOWYiuæɑəɛɪɹʊʌ")
61		vsRe       = regexp.MustCompile(`(?i)^vs\.?$`)
