65	// because RE2 has no backreferences: "stopping" and "trafficking" drop four
66	// characters to reach their stem, not three.
67	func doubledIng(word string) bool {
68		rs := []rune(word)
69		if len(rs) < 5 || string(rs[len(rs)-3:]) != "ing" {
70			return false
71		}
72		a, b := rs[len(rs)-5], rs[len(rs)-4]
73		if a == 'c' && b == 'k' {
74			return true
75		}
76		return a == b && strings.ContainsRune("bcdgklmnprstvxz", a)
77	}
