80	// two ASCII alphabets. A word containing anything else is not looked up at
81	// all — which is why `café` goes to the fallback, as misaki's own TODO says.
82	func inLexiconOrds(r rune) bool {
83		return r == '\'' || r == '-' || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z')
