86	// Load reads the two dictionaries `reference/convert_misaki.py` exports.
87	//
88	// dir is the directory holding `us_gold.txt` and `us_silver.txt` (or the `gb_`
89	// pair). Both are plain text, one entry per line, so this is a scan rather
90	// than a JSON parse: 183 thousand entries in about 60 ms.
91	func Load(dir string, british bool) (*Lexicon, error) {
92		prefix := "us"
93		if british {
94			prefix = "gb"
95		}
96		l := &Lexicon{British: british, capStresses: [2]float64{0.5, 2}}
97		var err error
98		if l.gold, err = readDict(filepath.Join(dir, prefix+"_gold.txt")); err != nil {
99			return nil, err
100		}
101		if l.silver, err = readDict(filepath.Join(dir, prefix+"_silver.txt")); err != nil {
102			return nil, err
103		}
104		l.gold = growDictionary(l.gold)
105		l.silver = growDictionary(l.silver)
106		return l, nil
107	}
108	
109	func readDict(path string) (map[string]entry, error) {
110		f, err := os.Open(path)
111		if err != nil {
112			return nil, fmt.Errorf("g2p: %w (run reference/convert_misaki.py)", err)
113		}
114		defer f.Close()
