116		sc := bufio.NewScanner(f)
117		sc.Buffer(make([]byte, 0, 1<<16), 1<<20)
118		for sc.Scan() {
119			line := sc.Text()
120			word, value, ok := strings.Cut(line, "\t")
121			if !ok || word == "" {
