139	// capitalised form and vice versa, with the originals winning any collision.
140	//
141	// It is what makes `Fox` find `fox` without a separate case-folding pass in
142	// every lookup — and it has to run after both files are read, because the
143	// added forms must not shadow a real entry.
144	func growDictionary(d map[string]entry) map[string]entry {
145		out := make(map[string]entry, len(d)*2)
146		for k, v := range d {
