			n    int64
			unit string
		}
		var pairs []amount
		for i, p := range parts {
			if i >= len(units) {
				break
			}
			var n int64
			if p != "" {
				n, _ = strconv.ParseInt(p, 10, 64)
			}
			pairs = append(pairs, amount{n, units[i]})
		}
