		case !strings.Contains(word, "."):
			n, err := strconv.ParseInt(plain, 10, 64)
			if err != nil {
				return "", 0, false
			}
			if ordinalSuffixes[suffix] {
				text = Ordinal(n)
			} else {
				text = Cardinal(n)
			}
