			// A bare fraction: "point one two five", each digit its own word.
			var b strings.Builder
			b.WriteString("point")
			for _, d := range plain[1:] {
				b.WriteString(" ")
				b.WriteString(lowNumWords[d-'0'])
			}
			text = b.String()
