	switch suffix {
	case "s", "'s":
		out, _ = l.suffixS(out)
	case "ed", "'d":
		out, _ = l.suffixEd(out)
	case "ing":
		out, _ = l.suffixIng(out)
	}
	return out, rating, true
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

