	case s == "":
		return ""
	case IsNumber(s, true):
		return "CD"
	case s == "I":
		return "PRP"
	}
	lower := strings.ToLower(s)
	switch lower {
	case "a", "an", "the":
		return "DT"
	case "to":
		return "TO"
	case "in", "of", "by", "for", "with", "at", "on", "from", "as", "into",
		"than", "through", "over", "under", "about", "since", "without":
		return "IN"
	}
	if !isWordy(s) {
		if alone && (s == "-" || s == "–") {
			return ":"
		}
		return "."
	}
