// has worked out about it so far.
type Token struct {
	Text       string
	Tag        string
	Whitespace string

	Phonemes string
	Resolved bool // Phonemes is meaningful, even when it is empty
	Rating   int

	IsHead   bool
	Currency string
	NumFlags string
	Prespace bool
