// is rules — whitespace, then its own `Subtokenize` over each chunk — and that
// is reproduced here exactly. The *tagging* is a neural model, and T5a measured
// what it is worth: a part-of-speech tag decides 1.74% of tokens over 69
// distinct words. So the tags here come from `tagOf`, which is a handful of
// rules, and `TestPhonemize` reports what that costs rather than hiding it.
func Tokenize(text string) []*Token {
	var out []*Token
	text = strings.TrimLeft(text, " \t\n\r")
	rs := []rune(text)
	sentenceStart := true
	for i := 0; i < len(rs); {
		// One whitespace-delimited chunk, and the whitespace after it.
		j := i
		for j < len(rs) && !unicode.IsSpace(rs[j]) {
			j++
		}
		chunk := string(rs[i:j])
		k := j
		for k < len(rs) && unicode.IsSpace(rs[k]) {
			k++
		}
		space := " "
		if k == len(rs) {
			space = ""
		}
		i = k
		if chunk == "" {
			continue
		}
		parts := Subtokenize(chunk)
		for p, s := range parts {
			tk := &Token{Text: s, IsHead: true}
